import {useEffect,useMemo,useState} from 'react';

const sampleUsers=Array.from({length:27},(_,i)=>({
 id:i+1,
 name:['Aarav Sharma','Diya Patel','Kri Kumar','Maya Rao','Rishi Singh'][i%5]+' '+(i+1),
 email:'developer'+(i+1)+'@example.com',
 company:{name:i%2?'Frontend team':'Backend team'}
}));

export default function App(){
 const [source,setSource]=useState('sample');
 const [users,setUsers]=useState([]);
 const [loading,setLoading]=useState(true);
 const [error,setError]=useState('');
 const [retry,setRetry]=useState(0);
 const [query,setQuery]=useState('');
 const [team,setTeam]=useState('All');
 const [page,setPage]=useState(1);
 const [pageSize,setPageSize]=useState(5);

 useEffect(()=>{
  const controller=new AbortController();
  let active=true;
  // A local JSON fixture keeps this exercise usable without internet.
  const sampleUrl=URL.createObjectURL(new Blob([JSON.stringify(sampleUsers)],{type:'application/json'}));
  const url=source==='live'?'https://jsonplaceholder.typicode.com/users':sampleUrl;
  setLoading(true);setError('');setUsers([]);
  async function load(){
   try{
    const response=await fetch(url,{signal:controller.signal});
    if(!response.ok)throw new Error('Request failed: HTTP '+response.status);
    const data=await response.json();
    if(!Array.isArray(data)||data.some(user=>typeof user.id!=='number'||typeof user.name!=='string'||typeof user.email!=='string'))throw new Error('Invalid user list received');
    if(active)setUsers(data);
   }catch(err){if(active&&err.name!=='AbortError')setError(err.message);}
   finally{if(active)setLoading(false);}
  }
  load();
  return()=>{active=false;controller.abort();URL.revokeObjectURL(sampleUrl);};
 },[source,retry]);

 const teams=['All',...new Set(users.map(u=>u.company?.name||'Unassigned'))];
 const filtered=useMemo(()=>users.filter(user=>{
  const matchesSearch=(user.name+' '+user.email).toLowerCase().includes(query.trim().toLowerCase());
  const matchesTeam=team==='All'||(user.company?.name||'Unassigned')===team;
  return matchesSearch&&matchesTeam;
 }),[users,query,team]);
 const pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));
 const currentPage=Math.min(page,pageCount);
 const rows=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize);

 return <section>
  <h2>Fetch users · search · filter · paginate</h2>
  <label>Data source <select value={source} onChange={e=>{setSource(e.target.value);setTeam('All');setPage(1);}}>
   <option value='sample'>Local sample JSON (offline)</option>
   <option value='live'>Public demo API (internet)</option>
  </select></label>
  <p>{source==='sample'?'27 sample users, loaded with fetch from a local JSON Blob.':'Live GET request to JSONPlaceholder /users.'}</p>
  {loading?<p role='status'>Loading users…</p>:error?<div role='alert'><p>{error}</p><button onClick={()=>setRetry(n=>n+1)}>Retry request</button></div>:<>
   <div>
    <label>Search <input placeholder='Name or email' value={query} onChange={e=>{setQuery(e.target.value);setPage(1);}}/></label>
    <label>Company <select value={team} onChange={e=>{setTeam(e.target.value);setPage(1);}}>{teams.map(t=><option key={t}>{t}</option>)}</select></label>
    <label>Rows <select value={pageSize} onChange={e=>{setPageSize(Number(e.target.value));setPage(1);}}>{[5,10,20].map(size=><option key={size} value={size}>{size}</option>)}</select></label>
   </div>
   <table><caption>Users ({filtered.length} matching)</caption><thead><tr><th scope='col'>ID</th><th scope='col'>Name</th><th scope='col'>Email</th><th scope='col'>Company</th></tr></thead><tbody>
    {rows.map(user=><tr key={user.id}><td>{user.id}</td><td>{user.name}</td><td>{user.email}</td><td>{user.company?.name||'Unassigned'}</td></tr>)}
    {!rows.length&&<tr><td colSpan={4}>No matching users. Change the search or filter.</td></tr>}
   </tbody></table>
   <nav aria-label='Table pagination'><button disabled={currentPage<=1} onClick={()=>setPage(currentPage-1)}>Previous</button><span aria-live='polite'> Page {currentPage} of {pageCount} </span><button disabled={currentPage>=pageCount} onClick={()=>setPage(currentPage+1)}>Next</button></nav>
  </>}
 </section>;
}

